import { ArrowRight, ArrowUpRight, Gamepad2, Menu, Search, ShoppingBag, UserRound, X } from 'lucide-react';

type User = { name: string; email: string };
type Page = 'home' | 'store' | 'cart' | 'orders';

type Props = {
  cartCount: number;
  mobileNav: boolean;
  user: User | null;
  query: string;
  setQuery: (value: string) => void;
  setMobileNav: (open: boolean) => void;
  navigate: (page: Page) => void;
  setPlatform: (platform: string) => void;
  setApplied: (query: string) => void;
  openAuth: (mode?: 'login' | 'register') => void;
  logout: () => void;
  submitSearch: (event: React.FormEvent<HTMLFormElement>) => void;
};

export default function MarketplaceHeader(props: Props) {
  const { cartCount, mobileNav, user, query, setQuery, setMobileNav, navigate, setPlatform, setApplied, openAuth, logout, submitSearch } = props;
  return <>
    <div className="announcement"><span>AMEBA PLAYER DEAL</span><i/> Great games, good prices. Your next play starts here. <ArrowRight size={13}/></div>
    <header className="header">
      <div className="header-main">
        <button className="mobile-menu icon-btn" onClick={() => setMobileNav(!mobileNav)} aria-label="Toggle navigation">{mobileNav ? <X/> : <Menu/>}</button>
        <button className="brand" onClick={() => navigate('home')} aria-label="AMEBA home"><img src="/ameba-logo.svg" alt="AMEBA"/></button>
        <form className="search" onSubmit={submitSearch}>
          <Search size={19}/><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search games and more" aria-label="Search games"/><kbd>↵</kbd>
        </form>
        <div className="market-locale"><span className="locale-dot"/> English EU <span className="locale-divider">|</span> EUR</div>
        <div className="header-actions">
          <button className="icon-btn profile-btn" onClick={() => user ? navigate('orders') : openAuth()} title={user?.name || 'Sign in'}><UserRound size={19}/><span>{user ? user.name.split(' ')[0] : 'Sign in'}</span></button>
          <button className="cart-button" onClick={() => navigate('cart')}><ShoppingBag size={19}/><span>Cart</span><b>{cartCount}</b></button>
        </div>
      </div>
      <nav className={`nav ${mobileNav ? 'nav-open' : ''}`} aria-label="Game categories">
        <button className="nav-category" onClick={() => { setApplied(''); setPlatform(''); navigate('store'); }}><Gamepad2 size={15}/> Categories</button>
        <button onClick={() => { setApplied(''); setPlatform(''); navigate('store'); }}>Cheap games</button>
        <button onClick={() => { setPlatform('PC'); navigate('store'); }}>PC games</button>
        <button onClick={() => { setPlatform('PlayStation 5'); navigate('store'); }}>PlayStation</button>
        <button onClick={() => { setPlatform('Xbox Series X|S'); navigate('store'); }}>Xbox</button>
        <button onClick={() => { setApplied(''); navigate('store'); }}>Gift cards</button>
        <button className="nav-sale" onClick={() => { setApplied(''); navigate('store'); }}>Deals <span>HOT</span></button>
        <div className="nav-spacer"/>
        {user ? <><button className="welcome">Hey, {user.name.split(' ')[0]}</button><button onClick={logout}>Sign out</button></> : <button onClick={() => openAuth('register')}>Register <ArrowUpRight size={13}/></button>}
      </nav>
    </header>
  </>;
}

import { ArrowRight, ChevronRight, CirclePercent, Gamepad2, Monitor, Play, Sparkles, Zap } from 'lucide-react';
import type { Product } from './types';

type Props = {
  banner: { eyebrow?: string; title?: string; description?: string; cta?: string } | null;
  featured: Product | undefined;
  navigate: (page: 'home' | 'store' | 'cart' | 'orders') => void;
  setPlatform: (platform: string) => void;
};

export default function HomePage({ banner, featured, navigate, setPlatform }: Props) {
  const toPlatform = (platform: string) => { setPlatform(platform); navigate('store'); };
  return <div className="home-page">
    <section className="home-campaign">
      <div className="campaign-art" style={featured ? { backgroundImage: `linear-gradient(90deg, #22104b 0%, rgba(34,16,75,.91) 35%, rgba(34,16,75,.12) 100%), url(${featured.image})` } : undefined}/>
      <div className="campaign-copy">
        <div className="campaign-eyebrow"><span/> {banner?.eyebrow || 'AMEBA PICKS'}</div>
        <h1>{banner?.title || <>Great games.<br/>Better prices.</>}</h1>
        <p>{banner?.description || 'Find your next game at a price worth playing.'}</p>
        <button className="campaign-cta" onClick={() => navigate('store')}>{banner?.cta || 'Shop games'} <ArrowRight size={16}/></button>
      </div>
      {featured && <button className="campaign-product" onClick={() => navigate('store')}>
        <span className="campaign-product-label"><Zap size={13}/> FEATURED GAME</span>
        <b>{featured.title}</b><span>From <strong>€{Number(featured.price).toFixed(2)}</strong></span>
      </button>}
      <div className="campaign-count"><b>01</b><span/><small>01</small></div>
    </section>

    <section className="market-shortcuts" aria-label="Shop by category">
      <button onClick={() => { setPlatform(''); navigate('store'); }}><span><Gamepad2/></span><b>All games</b></button>
      <button onClick={() => toPlatform('PC')}><span><Monitor/></span><b>PC</b></button>
      <button onClick={() => toPlatform('PlayStation 5')}><span className="shortcut-play"><Play/></span><b>PlayStation</b></button>
      <button onClick={() => toPlatform('Xbox Series X|S')}><span className="shortcut-xbox"><Gamepad2/></span><b>Xbox</b></button>
      <button onClick={() => toPlatform('Nintendo Switch')}><span className="shortcut-nintendo">N</span><b>Nintendo</b></button>
      <button onClick={() => navigate('store')}><span><CirclePercent/></span><b>Deals</b></button>
      <button className="shortcut-all" onClick={() => navigate('store')}>All offers <ChevronRight size={14}/></button>
    </section>
    <div className="home-trustline"><span><Zap size={14}/> Instant digital delivery</span><i/><span><Gamepad2 size={14}/> Great games, ready to play</span><i/><span><Sparkles size={14}/> Deals picked for players</span></div>
  </div>;
}

