const r = await tools.exec_command({cmd:"$css = @'

/* AMEBA marketplace refresh: bright violet shell, compact utility header, campaign banner and dense catalog shelves. */
:root { font-family: Inter, "Segoe UI", Arial, sans-serif; }
body { background: #4d20b5; font-family: Inter, "Segoe UI", Arial, sans-serif; }
.app-shell.ameba-shell { max-width: 1440px; background: #4d20b5; color: #fff; font-family: Inter, "Segoe UI", Arial, sans-serif; }
.app-shell.ameba-shell.home-active { background: #4d20b5; }
.ameba-shell .announcement { height: 27px; gap: 8px; color: #fff; background: #391487; font: 600 9px Inter, "Segoe UI", Arial, sans-serif; letter-spacing: .35px; }
.ameba-shell .announcement span { color: #d5f46a; font-weight: 800; letter-spacing: .7px; }
.ameba-shell .announcement i { width: 3px; height: 3px; border-radius: 50%; background: #bb9cff; }
.ameba-shell .header { background: #5422bf; border-bottom: 0; }
.ameba-shell .header-main { height: 69px; padding: 0 3.5%; gap: 22px; }
.ameba-shell .brand { width: 132px; flex: 0 0 132px; height: 42px; }
.ameba-shell .brand img { display: block; width: 100%; height: 100%; object-fit: contain; }
.ameba-shell .search { height: 41px; max-width: 600px; border: 1px solid #a78ae6; border-radius: 2px; background: #4b1caa; color: #fff; }
.ameba-shell .search input { color: #fff; font-size: 12px; }
.ameba-shell .search input::placeholder { color: #d1c2f0; }
.ameba-shell .search kbd { border-color: #9775de; color: #e5dafa; }
.market-locale { display: flex; align-items: center; gap: 6px; flex: 0 0 auto; color: #f4efff; white-space: nowrap; font-size: 10px; }
.locale-dot { width: 8px; height: 8px; border-radius: 50%; background: linear-gradient(180deg,#f2c43c 0 33%,#35b978 33% 66%,#e65b79 66%); }
.locale-divider { color: #c0a9ed; }
.ameba-shell .header-actions { gap: 16px; }
.ameba-shell .header-actions .icon-btn, .ameba-shell .cart-button { color: #fff; }
.ameba-shell .header-actions button { font-size: 11px; }
.ameba-shell .cart-button b { color: #29105e; background: #d5f46a; }
.ameba-shell .nav { height: 40px; padding: 0 3.5%; gap: 23px; background: #391487; border-top: 1px solid #6936c6; }
.ameba-shell .nav button { color: #f2edfb; font-size: 10px; }
.ameba-shell .nav button:hover { color: #d5f46a; }
.ameba-shell .nav .nav-category { color: #fff; }
.ameba-shell .nav .nav-sale span { color: #2f176b; background: #d5f46a; }
.home-active main { background: #4d20b5; }
.home-campaign { position: relative; isolation: isolate; height: clamp(245px, 29vw, 360px); margin: 17px 24px 0; overflow: hidden; background: #281054; }
.campaign-art { position: absolute; inset: 0; z-index: -1; background-color: #281054; background-size: cover; background-position: center 40%; }
.campaign-copy { position: relative; z-index: 1; width: min(55%, 610px); height: 100%; padding: 38px 0 28px 5%; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; }
.campaign-eyebrow { display: flex; align-items: center; gap: 8px; color: #e2d8f5; font-size: 9px; font-weight: 800; letter-spacing: 1px; }
.campaign-eyebrow span { width: 7px; height: 7px; border-radius: 50%; background: #d5f46a; }
.campaign-copy h1 { margin: 13px 0 9px; color: #fff; font: 750 clamp(34px, 4vw, 55px)/1.02 Inter, "Segoe UI", Arial, sans-serif; letter-spacing: -1.5px; white-space: pre-line; }
.campaign-copy p { max-width: 370px; margin: 0; color: #e1d7f2; font-size: 12px; line-height: 1.55; }
.campaign-cta { display: inline-flex; align-items: center; gap: 12px; height: 40px; margin-top: 20px; padding: 0 17px; color: #241044; background: #ffe237; font-size: 10px; font-weight: 800; }
.campaign-cta:hover { background: #ffeb69; }
.campaign-product { position: absolute; right: 27px; bottom: 24px; width: 216px; min-height: 80px; padding: 12px 14px; display: grid; gap: 6px; text-align: left; color: #fff; background: #35127ddd; border: 1px solid #a987e7; }
.campaign-product-label { display: flex; align-items: center; gap: 5px; color: #d5f46a; font: 800 8px Inter, "Segoe UI", Arial, sans-serif; letter-spacing: .7px; }
.campaign-product b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 11px; }
.campaign-product>span:last-child { color: #d7c9ef; font-size: 9px; }
.campaign-product strong { color: #d5f46a; font-size: 14px; }
.campaign-count { position: absolute; right: 28px; top: 19px; display: flex; align-items: center; gap: 8px; color: #e3d8f2; font-size: 9px; }
.campaign-count b { color: #fff; }
.campaign-count span { width: 30px; height: 2px; background: #d5f46a; }
.market-shortcuts { display: flex; align-items: stretch; gap: 1px; min-height: 83px; margin: 12px 24px 0; overflow-x: auto; background: #3b1689; }
.market-shortcuts button { min-width: 88px; flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; color: #fff; background: transparent; }
.market-shortcuts button:hover { background: #5121ae; }
.market-shortcuts button>span { height: 26px; display: grid; place-items: center; color: #fff; }
.market-shortcuts button svg { width: 22px; height: 22px; stroke-width: 1.8; }
.market-shortcuts button b { font-size: 9px; font-weight: 650; white-space: nowrap; }
.market-shortcuts .shortcut-play { color: #fff; }
.market-shortcuts .shortcut-xbox { color: #d5f46a; }
.market-shortcuts .shortcut-nintendo { font: 800 21px Inter, "Segoe UI", Arial, sans-serif; }
.market-shortcuts .shortcut-all { min-width: 96px; flex: 0 0 auto; flex-direction: row; gap: 4px; color: #e4d6fb; font-size: 9px; }
.home-trustline { min-height: 38px; margin: 0 24px; display: flex; align-items: center; justify-content: center; gap: 19px; border-bottom: 1px solid #7544d0; color: #e5dafa; font-size: 9px; }
.home-trustline span { display: flex; align-items: center; gap: 6px; }
.home-trustline svg { color: #d5f46a; }
.home-trustline i { width: 2px; height: 2px; border-radius: 50%; background: #b89ce9; }
.home-shelves { padding: 0 24px; }
.home-shelves .product-section { padding: 24px 0 4px; }
.home-shelves .section-heading { margin-bottom: 14px; }
.home-shelves .section-heading h2 { margin: 5px 0 3px; font-size: 21px; letter-spacing: -.45px; }
.home-shelves .section-heading p { color: #e2d8f1; font-size: 10px; }
.home-shelves .section-kicker { color: #e0d1f8; font-size: 8px; }
.home-shelves .view-link { color: #fff; font-weight: 700; }
.home-shelves .product-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 14px; }
.home-shelves .product-card { overflow: hidden; border: 1px solid #7c4bd1; border-radius: 2px; background: #34117d; }
.home-shelves .product-card:hover { border-color: #d5f46a; transform: translateY(-1px); }
.home-shelves .card-art { height: 177px; background-color: #321270; }
.home-shelves .tag { color: #291253; background: #d5f46a; border: 0; border-radius: 1px; font-size: 8px; font-weight: 750; }
.home-shelves .heart { border-radius: 2px; }
.home-shelves .card-info { padding: 10px 11px 11px; }
.home-shelves .card-info .small { color: #d8c8f4; }
.home-shelves .title-button { min-height: 28px; color: #fff; font-size: 10px; }
.home-shelves .price-row { margin-top: 9px; }
.home-shelves .price-row strong { font-size: 17px; }
.home-shelves .old-price { color: #d1c2e9; }
.home-shelves .discount { color: #d5f46a; background: #5b389b; font-weight: 800; }
.home-shelves .quick-add { height: 30px; margin-top: 9px; color: #261148; background: #ffe237; border: 0; border-radius: 1px; font-weight: 750; }
.home-shelves .quick-add:hover { color: #261148; background: #ffeb69; }
.home-shelves .loading-grid { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 14px; }
.home-shelves .skeleton { height: 280px; border-radius: 2px; background: #612eb9; animation: none; }
.home-active .newsletter { margin: 30px 24px 42px; padding: 20px 22px; border: 1px solid #8051d2; border-radius: 2px; background: #3a1687; }
.home-active .newsletter h3 { margin: 4px 0; font-size: 17px; }
.home-active .newsletter p { color: #ddd2f0; }
.home-active .newsletter input { border-radius: 2px; }
.home-active .newsletter .primary-btn { color: #241044; background: #ffe237; border-radius: 1px; }
.ameba-shell .footer { background: #34117d; }
.ameba-shell .footer-main { border-top: 1px solid #7244c2; }
.ameba-shell .footer-bottom { border-top: 1px solid #5931a2; color: #d0c1e8; }
.ameba-shell .footer-news input { border-radius: 2px; }
.ameba-shell .footer-news form button { color: #241044; background: #ffe237; border-radius: 0; }
.ameba-shell .footer-col button { color: #d8c9ef; }
.ameba-shell .footer-brand p { color: #d8c9ef; }
.ameba-shell .toast { background: #35127d; }
@media (max-width: 1020px) {
  .ameba-shell .header-main { gap: 14px; }
  .market-locale { display: none; }
  .home-shelves .product-grid, .home-shelves .loading-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .home-shelves .product-card:nth-child(n+4) { display: none; }
}
@media (max-width: 650px) {
  .ameba-shell .announcement { font-size: 8px; }
  .ameba-shell .header-main { height: 60px; gap: 10px; padding: 0 12px; }
  .ameba-shell .brand { width: 96px; flex-basis: 96px; height: 34px; }
  .ameba-shell .search { height: 36px; }
  .ameba-shell .search input { font-size: 10px; }
  .ameba-shell .header-actions { gap: 8px; }
  .ameba-shell .cart-button b { width: 18px; height: 18px; }
  .ameba-shell .nav { padding: 0 12px; gap: 0; }
  .ameba-shell .nav.nav-open { display: grid; grid-template-columns: repeat(3, 1fr); }
  .ameba-shell .nav button { padding: 10px 3px; }
  .ameba-shell .nav-spacer { display: none; }
  .home-campaign { height: 302px; margin: 10px 10px 0; }
  .campaign-art { background-position: 64% center; }
  .campaign-copy { width: 82%; padding: 26px 0 24px 18px; }
  .campaign-copy h1 { font-size: 35px; letter-spacing: -.8px; }
  .campaign-copy p { max-width: 235px; font-size: 10px; }
  .campaign-cta { height: 36px; margin-top: 14px; }
  .campaign-product { right: 10px; bottom: 10px; width: 169px; min-height: 63px; padding: 8px 9px; }
  .campaign-product b { font-size: 9px; }
  .campaign-product strong { font-size: 12px; }
  .campaign-count { right: 12px; top: 10px; }
  .market-shortcuts { min-height: 74px; margin: 8px 10px 0; }
  .market-shortcuts button { min-width: 74px; }
  .market-shortcuts .shortcut-all { min-width: 73px; }
  .market-shortcuts button svg { width: 19px; height: 19px; }
  .market-shortcuts button b { font-size: 8px; }
  .home-trustline { margin: 0 10px; gap: 9px; font-size: 7px; }
  .home-trustline span { gap: 4px; }
  .home-trustline svg { width: 12px; }
  .home-shelves { padding: 0 10px; }
  .home-shelves .product-section { padding-top: 19px; }
  .home-shelves .section-heading h2 { font-size: 17px; }
  .home-shelves .section-heading p { font-size: 8px; }
  .home-shelves .product-grid, .home-shelves .loading-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .home-shelves .product-card:nth-child(n+4) { display: none; }
  .home-shelves .card-art { height: 128px; }
  .home-shelves .card-info { padding: 8px; }
  .home-shelves .price-row strong { font-size: 14px; }
  .home-active .newsletter { margin: 22px 10px 30px; padding: 14px; gap: 10px; }
  .home-active .newsletter form { grid-column: 1 / 3; }
  .ameba-shell .footer-main { padding: 28px 15px; }
  .ameba-shell .footer-bottom { padding: 11px 12px; }
}
